// Parse and classify incident
const incident = $input.first().json;

// Determine severity based on rules
let severity = 'P3'; // Default: low
let channel = '#ops-alerts';
let escalate = false;

const title = (incident.title || incident.message || '').toLowerCase();
const source = incident.source || 'unknown';
const errorRate = incident.error_rate || 0;
const affectedUsers = incident.affected_users || 0;

// P0: Critical - Complete outage
if (
  title.includes('outage') ||
  title.includes('down') ||
  errorRate > 50 ||
  affectedUsers > 1000 ||
  incident.severity === 'critical'
) {
  severity = 'P0';
  channel = '#incidents';
  escalate = true;
}
// P1: High - Major degradation
else if (
  title.includes('degraded') ||
  title.includes('slow') ||
  errorRate > 10 ||
  affectedUsers > 100 ||
  incident.severity === 'high'
) {
  severity = 'P1';
  channel = '#incidents';
  escalate = true;
}
// P2: Medium - Partial impact
else if (
  errorRate > 1 ||
  affectedUsers > 10 ||
  incident.severity === 'medium'
) {
  severity = 'P2';
  channel = '#ops-alerts';
}

return [{
  json: {
    id: `INC-${Date.now()}`,
    severity,
    title: incident.title || 'Unnamed Incident',
    description: incident.description || incident.message || 'No description',
    source,
    error_rate: errorRate,
    affected_users: affectedUsers,
    channel,
    escalate,
    raw: incident,
    created_at: new Date().toISOString()
  }
}];

